def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    if n >= 99:
        return 'D'

    opp_d = 0
    my_d = 0
    for m, o in history:
        if m == 'D':
            my_d += 1
        if o == 'D':
            opp_d += 1

    opp_c = n - opp_d

    # Exploit opponents that never defect, but only after confirming they tolerate a D.
    seen_d_coop = False
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i + 1][1] == 'C':
            seen_d_coop = True
            break

    if opp_d == 0:
        if my_d == 0:
            if n >= 8:
                return 'D'
            return 'C'
        if seen_d_coop:
            return 'D'
        return 'C'

    # If the opponent has never cooperated, defect forever.
    if opp_c == 0:
        return 'D'

    my_last, opp_last = history[-1]

    # Recent opponent D streak, useful for breaking punishment cycles.
    streak = 0
    for _, o in reversed(history):
        if o == 'D':
            streak += 1
        else:
            break

    # Overall and recent cooperation rates.
    recent_len = min(20, n)
    recent = history[-recent_len:]
    recent_opp_c = 0
    for _, o in recent:
        if o == 'C':
            recent_opp_c += 1

    overall_rate = opp_c / float(n)
    recent_rate = recent_opp_c / float(recent_len)

    # Estimate opponent's tendency to cooperate after our C and after our D.
    w_len = min(16, n)
    w = history[-w_len:]
    rc = 0
    rc_c = 0
    rd = 0
    rd_c = 0
    for i in range(len(w) - 1):
        m = w[i][0]
        o_next = w[i + 1][1]
        if m == 'C':
            rc += 1
            if o_next == 'C':
                rc_c += 1
        else:
            rd += 1
            if o_next == 'C':
                rd_c += 1

    fc = 0
    fc_c = 0
    fd = 0
    fd_c = 0
    for i in range(n - 1):
        m = history[i][0]
        o_next = history[i + 1][1]
        if m == 'C':
            fc += 1
            if o_next == 'C':
                fc_c += 1
        else:
            fd += 1
            if o_next == 'C':
                fd_c += 1

    if rc >= 4:
        p_c = (rc_c + 1.0) / (rc + 2.0)
    elif fc > 0:
        p_c = (fc_c + 1.0) / (fc + 2.0)
    else:
        p_c = 0.5

    if rd >= 4:
        p_d = (rd_c + 1.0) / (rd + 2.0)
    elif fd > 0:
        p_d = (fd_c + 1.0) / (fd + 2.0)
    else:
        p_d = 0.5

    # Opponent tolerates D and is generally cooperative: exploit.
    if p_d >= 0.68 and (overall_rate >= 0.55 or recent_rate >= 0.55):
        return 'D'

    # Opponent is reciprocal but cooperative: forgiving tit-for-tat.
    if p_d <= 0.48 and (overall_rate >= 0.45 or recent_rate >= 0.40):
        if opp_last == 'D':
            provoked = n >= 2 and history[-2][0] == 'D'
            if provoked and streak == 1 and p_c >= 0.6:
                return 'C'
            return 'D'

        if my_last == 'D':
            if p_c >= 0.55:
                return 'C'
            return 'D'

        if recent_rate < 0.45 or overall_rate < 0.5:
            return 'D'
        return 'C'

    # Obvious hostiles: do not feed them CC.
    if opp_d >= n - 2 or recent_rate <= 0.25 or overall_rate <= 0.35:
        return 'D'

    if opp_last == 'D':
        provoked = n >= 2 and history[-2][0] == 'D'

        # If we provoked a single D from a cooperative opponent, try to restore.
        if provoked and streak == 1:
            if recent_rate >= 0.55 or overall_rate >= 0.55:
                return 'C'
            return 'D'

        # Sustained aggression should be met with sustained defection.
        if streak >= 2:
            return 'D'

        # Punish isolated defection by otherwise cooperative opponents.
        if opp_d <= max(2, n // 8) and recent_rate >= 0.75:
            return 'D'

        # Forgive only very early isolated noise-like behavior.
        if opp_d <= 1 and n <= 18 and recent_rate >= 0.7:
            return 'C'

        return 'D'

    # Opponent cooperated last.
    if my_last == 'D':
        # They did not punish our recent D strongly. A cooperative, nonpunishing
        # opponent is profitable to exploit, while a reciprocal one is handled later.
        if recent_rate >= 0.6 and opp_d <= max(3, (2 * n) // 5):
            return 'D'
        return 'C'

    # Optional probe against opponents that are mostly cooperative but not pure.
    if my_d == 0 and n >= 20 and opp_d <= max(3, (2 * n) // 5) and recent_rate >= 0.55:
        return 'D'

    # Punish high or repeated defection.
    if opp_d * 5 >= n * 3 and n >= 15:
        return 'D'

    # If we have already defected several times and they rarely retaliate, keep pressure.
    if my_d >= 3 and opp_d <= 1:
        return 'D'

    # Late-game tie-break: exploit if cooperation is likely and punishment is not evident.
    if n >= 90 and recent_rate >= 0.65 and p_d >= 0.5:
        return 'D'

    return 'C'
